import{_ as a,o as t,c as s,a0 as r}from"./chunks/framework.dDzXfurR.js";const m=JSON.parse('{"title":"springcloud-day01","description":"学习MP的思考","frontmatter":{"title":"springcloud-day01","description":"学习MP的思考","date":"2026-10-05T00:00:00.000Z","tags":["java","后端"]},"headers":[],"relativePath":"posts/springcloud-day01.md","filePath":"posts/springcloud-day01.md","lastUpdated":1791736239000}'),i={name:"posts/springcloud-day01.md"};function o(n,e,l,d,c,g){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="mp学习笔记" tabindex="-1">MP学习笔记 <a class="header-anchor" href="#mp学习笔记" aria-label="Permalink to &quot;MP学习笔记&quot;">​</a></h1><p>今天学习的MP的基础认识，我发现一个之前写苍穹外卖不同的注入方法。 首先是原注入方法是@Autowired 但是今天是通过对controller层的@RequiredArgsConstructor注解的注入方式 原因是@Autowired会倒是循环依赖（而spring是通过三层缓存的方式来防止循环依赖的危险）。比如A依赖B，B也依赖A 导致整个程序出现无法判断具体谁依赖谁 所以今天学习了新的注入方式。<br> 学习了MP的代码生成器，通过表的字段可以自动生成Pojo/Mapper/Controller/Service<br> 学习了hutool的collutil.isEmpty() ai说这个比正常的判断更好，不清楚企业开发的什么，我觉得都可以<br> 学习了MP中的DB静态工具---可以在需要autowired其他mapper的时候只需要通过DB.lamdaQuery()即可调用其他表完成SQL语句的填写<br> 学习了逻辑删除的配置和使用 在xml文件中添加db-config:<br> logic-delete-field: flag 删除实体字段值 boolen..<br> logic-delete-value: 1 逻辑删除值<br> logic-not-delete-value: 0<br> 将1，2转换成枚举类的方式<br> 注：如果是json的话需要加enumvalue 在value上/jsonvalue在desc上<br> configuration: default-enum-type-handler: com.baomidou.mybatisplus.core.handlers.MybatisEnumTypeHandler<br> Json处理器:<br><img src="https://cdn.jsdelivr.net/gh/SFoneis/blog-images@main/images/da710e562b3956321992284a2606d2bc.png" alt=""><img src="https://cdn.jsdelivr.net/gh/SFoneis/blog-images@main/images/4e360180647256e90cb0c5eb0997c3c4.png" alt=""> 后续只需要通过即可 <img src="https://cdn.jsdelivr.net/gh/SFoneis/blog-images@main/images/e1755ac8d77b12a41ae6c35247293c4f.png" alt=""> 分页查询 <img src="https://cdn.jsdelivr.net/gh/SFoneis/blog-images@main/images/20261005223148360.png" alt=""><img src="https://cdn.jsdelivr.net/gh/SFoneis/blog-images@main/images/20261005223240433.png" alt=""> 了解到了把方法定义到类中中通过泛型可以更好的简化代码，要重新学习lamda了:)</p>',2)])])}const u=a(i,[["render",o]]);export{m as __pageData,u as default};
